import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import authService from '../services/authService';

// ─── Création du contexte ───────────────────────────────────────────────────
const AuthContext = createContext(null);

// ─── Provider ──────────────────────────────────────────────────────────────
export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);       // { id, name, email, role }
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true); // vérification initiale du token

  // Au montage : restaurer la session depuis localStorage
  useEffect(() => {
    const storedToken = localStorage.getItem('hotel_token');
    const storedUser  = localStorage.getItem('hotel_user');

    if (storedToken && storedUser) {
      try {
        setToken(storedToken);
        setUser(JSON.parse(storedUser));
        // Injecter le token dans les headers Axios globalement
        authService.setAuthHeader(storedToken);
      } catch {
        // Données corrompues → on nettoie
        localStorage.removeItem('hotel_token');
        localStorage.removeItem('hotel_user');
      }
    }
    setLoading(false);
  }, []);

  // ── Login ─────────────────────────────────────────────────────────────────
  const login = useCallback(async (credentials) => {
    const data = await authService.login(credentials);
    // data = { token, user: { id, name, email, role } }
    localStorage.setItem('hotel_token', data.token);
    localStorage.setItem('hotel_user',  JSON.stringify(data.user));
    authService.setAuthHeader(data.token);
    setToken(data.token);
    setUser(data.user);
    return data.user;
  }, []);

  // ── Register ──────────────────────────────────────────────────────────────
  const register = useCallback(async (userData) => {
    const data = await authService.register(userData);
    localStorage.setItem('hotel_token', data.token);
    localStorage.setItem('hotel_user',  JSON.stringify(data.user));
    authService.setAuthHeader(data.token);
    setToken(data.token);
    setUser(data.user);
    return data.user;
  }, []);

  // ── Logout ────────────────────────────────────────────────────────────────
  const logout = useCallback(() => {
    localStorage.removeItem('hotel_token');
    localStorage.removeItem('hotel_user');
    authService.removeAuthHeader();
    setToken(null);
    setUser(null);
  }, []);

  // ── Helpers rôles ─────────────────────────────────────────────────────────
  const isAdmin     = user?.role === 'admin';
  const isReceptionist = user?.role === 'receptionist';
  const isClient    = user?.role === 'client';
  const isAuthenticated = !!token;

  const value = {
    user,
    token,
    loading,
    isAuthenticated,
    isAdmin,
    isReceptionist,
    isClient,
    login,
    register,
    logout,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

// ─── Hook personnalisé ──────────────────────────────────────────────────────
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth doit être utilisé dans un <AuthProvider>');
  }
  return context;
};

export default AuthContext;
